      const play=document.createElement('button');play.type='button';play.className='tile-action';play.textContent='▶';play.setAttribute('aria-label','Start '+r.name);play.title='Start action';play.disabled=!connected||(!demo&&!status.robot_connected)||busy||status.state==='playing'||status.state==='paused';play.onclick=()=>startSelected(r);tile.append(primary,favorite);if(!isUniStore)tile.append(play);container.append(tile);
