  async function refresh(){try{if(demo){library=demoLibrary;motions=demoMotions;status={...status,robot_connected:false};}else{const [result,motionResult,latest,settings,preferences]=await Promise.all([request('/api/routines'),request('/api/motions').catch(()=>({motions:[]})),request('/api/status'),request('/api/settings'),request('/api/app-data/preferences').catch(()=>null)]);library=result.routines;motions=motionResult.motions;status=latest;audioOutput=settings.audio_output;setAudioOutput(audioOutput);applyPreferences(preferences);}if(selected?.kind!=='unistore'&&selected)selected=library.find(r=>r.id===selected.id)||motions.find(m=>m.id===selected.id)||null;connection(true,status.robot_connected);renderCards();renderPlayer();log('Library refreshed: '+library.length+' items');}catch(e){connection(false,false);toast('Could not connect. Join the G1 hotspot and check Settings.');renderCards();}}
  async function poll(){if(demo||polling||document.hidden)return;polling=true;try{let latest=await request('/api/status');const wasDanceActive=!!browserAudioDanceId&&['playing','paused'].includes(status.state),danceFinished=wasDanceActive&&!['playing','paused'].includes(latest.state);if(danceFinished)stopBrowserAudio();if(browserAudio&&browserAudioOnly&&!['playing','paused'].includes(latest.state))latest={...latest,state:'playing',routine_id:status.routine_id};if(!['playing','paused'].includes(latest.state)&&!browserAudio)musicOnlyPlayback=false;if(latest.state==='error'&&status.error!==latest.error)toast(latest.error||'Playback failed');status=latest;connection(true,status.robot_connected);}catch(e){connection(false,false);}finally{polling=false;}}
