  function deviceRow(device, mode){const row=document.createElement('div');row.className='bluetooth-device';const details=document.createElement('div');const name=document.createElement('strong');name.textContent=device.name;details.append(name);const button=document.createElement('button');button.type='button';button.className=device.connected?'subtle-button connected-device':'subtle-button';button.textContent=device.connected?'Connected':mode==='pair'?'Pair':'Connect';button.disabled=!!device.connected||busy;button.onclick=()=>bluetoothAction(mode==='pair'?'pair':'connect',device.address);row.append(details,button);return row;}
  function renderBluetooth(){const paired=$('bluetooth-paired-devices'),search=$('bluetooth-search-results');paired.replaceChildren();search.replaceChildren();if(!bluetoothDevices.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='No paired Bluetooth audio devices.';paired.append(empty);}else bluetoothDevices.forEach(device=>paired.append(deviceRow(device,'connect')));const pairedAddresses=new Set(bluetoothDevices.map(device=>device.address));bluetoothSearch.filter(device=>!pairedAddresses.has(device.address)).forEach(device=>search.append(deviceRow(device,'pair')));}
