  let studioNodes=[],studioLinks=[],studioSelectedLink=null,studioNodeSeq=0,studioLinkSeq=0,studioLinkSource=null,teleopTimer=null,teleopDirection=null;
  const studioKey='g1.studio.v1';
  const studioView=document.createElement('main');studioView.className='studio-view';studioView.id='studio-view';studioView.hidden=true;studioView.innerHTML='<header class="studio-header"><div><div class="eyebrow">CHOREOGRAPHY WORKSPACE</div><h1>Studio Mode</h1><p>Drag dances onto the canvas, connect their order, and add travel between them.</p></div><div class="studio-actions"><button class="subtle-button" id="studio-clear" type="button">Clear canvas</button><button class="accent-button" id="studio-run" type="button">▶ Run sequence</button></div></header><div class="studio-layout"><aside class="studio-palette"><h2>Dances</h2><p>Drag or click a dance to add it.</p><div id="studio-palette-list" class="studio-palette-list"></div></aside><section class="studio-canvas-wrap"><div class="studio-canvas-toolbar"><span>Drag nodes · connect output ● to input ●</span><button class="subtle-button" id="studio-add-delay" type="button">+ Delay node</button></div><div id="studio-canvas" class="studio-canvas" aria-label="Studio sequence canvas"><svg id="studio-links" class="studio-links" aria-hidden="true"></svg><div id="studio-empty" class="studio-empty">Drag a dance here to begin your sequence.</div></div></section><aside class="studio-inspector"><h2>Connection</h2><div id="studio-connection-empty" class="studio-inspector-empty">Select a connection to set its delay or travel movement.</div><form id="studio-connection-form" hidden><label class="field">Delay before next dance (seconds)<input id="studio-delay" type="number" min="0" max="120" step="0.1" value="0"></label><label class="field">Move direction<select id="studio-direction"><option value="none">No movement</option><option value="forward">Forward</option><option value="back">Backward</option><option value="left">Left</option><option value="right">Right</option></select></label><label class="field">Move for (seconds)<input id="studio-move-time" type="number" min="0.1" max="10" step="0.1" value="1"></label><button class="accent-button" type="submit">Save connection</button><button class="remove-action" id="studio-delete-link" type="button">Remove connection</button></form></aside><aside class="teleop-panel"><h2>Teleop</h2><p>Hold an arrow key or button to move. Release to stop. Requires Run Mode and a clear area.</p><div class="teleop-pad"><button data-teleop="forward" aria-label="Move forward">↑</button><button data-teleop="left" aria-label="Move left">←</button><button data-teleop="stop" aria-label="Stop movement" class="teleop-stop">■</button><button data-teleop="right" aria-label="Move right">→</button><button data-teleop="back" aria-label="Move backward">↓</button></div><small id="teleop-state">Stopped</small></aside></div>';$('library').closest('.main').after(studioView);
  function studioItems(){return [...library,...unistore.apps.map(item=>({...item,kind:'unistore',duration:item.duration||20,name:item.name||item.title||'UniStore dance'}))].filter(item=>item.kind!=='mimic'||!['recovery','utility'].includes(item.category));}
  function studioSave(){localStorage.setItem(studioKey,JSON.stringify({nodes:studioNodes,links:studioLinks}));}
  function studioLoad(){try{const saved=JSON.parse(localStorage.getItem(studioKey)||'{}');studioNodes=Array.isArray(saved.nodes)?saved.nodes:[];studioLinks=Array.isArray(saved.links)?saved.links:[];studioNodeSeq=studioNodes.reduce((max,node)=>Math.max(max,Number(String(node.id).replace('node-',''))||0),0);studioLinkSeq=studioLinks.reduce((max,link)=>Math.max(max,Number(String(link.id).replace('link-',''))||0),0);}catch{studioNodes=[];studioLinks=[];}}
  function studioNodeItem(node){return studioItems().find(item=>item.id===node.actionId&&item.kind===node.kind)||{id:node.actionId,kind:node.kind,name:node.name||'Unavailable dance',duration:node.duration||3};}
  function studioAdd(item,x=120+studioNodes.length*28,y=110+studioNodes.length*24){studioNodes.push({id:'node-'+(++studioNodeSeq),actionId:item.id,kind:item.kind,name:item.song_title||item.name,duration:Number(item.duration)||3,x,y});studioSave();renderStudio();}
  function studioAddDelay(){studioNodes.push({id:'node-'+(++studioNodeSeq),kind:'delay',name:'Wait',duration:0,x:150+studioNodes.length*25,y:130+studioNodes.length*22});studioSave();renderStudio();}
  function studioPortPoint(id,output){const port=document.querySelector('[data-studio-'+(output?'output':'input')+'="'+id+'"]'),canvas=$('studio-canvas');if(!port||!canvas)return null;const a=port.getBoundingClientRect(),b=canvas.getBoundingClientRect();return{x:a.left-b.left+a.width/2,y:a.top-b.top+a.height/2};}
  function renderStudioLinks(){const svg=$('studio-links');if(!svg)return;svg.replaceChildren();studioLinks.forEach(link=>{const from=studioPortPoint(link.from,true),to=studioPortPoint(link.to,false);if(!from||!to)return;const path=document.createElementNS('http://www.w3.org/2000/svg','path');const bend=Math.max(45,Math.abs(to.x-from.x)*.45);path.setAttribute('d','M '+from.x+' '+from.y+' C '+(from.x+bend)+' '+from.y+', '+(to.x-bend)+' '+to.y+', '+to.x+' '+to.y);path.classList.toggle('selected',link.id===studioSelectedLink);path.dataset.studioLink=link.id;path.onclick=()=>{studioSelectedLink=link.id;renderStudioInspector();renderStudioLinks();};svg.append(path);});}
  function renderStudioInspector(){const link=studioLinks.find(value=>value.id===studioSelectedLink);$('studio-connection-empty').hidden=!!link;$('studio-connection-form').hidden=!link;if(!link)return;$('studio-delay').value=link.delay||0;$('studio-direction').value=link.direction||'none';$('studio-move-time').value=link.moveTime||1;}
  function renderStudio(){if(!$('studio-palette-list'))return;const palette=$('studio-palette-list');palette.replaceChildren();studioItems().forEach(item=>{const button=document.createElement('button');button.className='studio-palette-item';button.type='button';button.draggable=true;button.textContent=item.song_title||item.name;button.title='Add '+(item.song_title||item.name);button.onclick=()=>studioAdd(item);button.ondragstart=event=>event.dataTransfer.setData('application/g1-dance',JSON.stringify({id:item.id,kind:item.kind,name:item.song_title||item.name,duration:item.duration||3}));palette.append(button);});const canvas=$('studio-canvas');canvas.querySelectorAll('.studio-node').forEach(node=>node.remove());$('studio-empty').hidden=studioNodes.length>0;studioNodes.forEach(node=>{const element=document.createElement('article');element.className='studio-node'+(node.kind==='delay'?' delay-node':'');element.dataset.studioNode=node.id;element.style.left=node.x+'px';element.style.top=node.y+'px';element.innerHTML='<button class="studio-port input" data-studio-input="'+node.id+'" aria-label="Connect into '+node.name+'">●</button><strong>'+node.name.replace(/[<&]/g,'')+'</strong><small>'+((node.kind==='delay')?'Delay node':node.kind+' · '+Math.round(node.duration||0)+' sec')+'</small><button class="studio-node-remove" aria-label="Remove '+node.name+'">×</button><button class="studio-port output" data-studio-output="'+node.id+'" aria-label="Connect from '+node.name+'">●</button>';const remove=element.querySelector('.studio-node-remove');remove.onclick=event=>{event.stopPropagation();studioNodes=studioNodes.filter(value=>value.id!==node.id);studioLinks=studioLinks.filter(value=>value.from!==node.id&&value.to!==node.id);studioSave();renderStudio();};element.onpointerdown=event=>{if(event.target.closest('button'))return;const startX=event.clientX,startY=event.clientY,originX=node.x,originY=node.y;element.setPointerCapture(event.pointerId);const move=next=>{node.x=Math.max(0,originX+next.clientX-startX);node.y=Math.max(0,originY+next.clientY-startY);element.style.left=node.x+'px';element.style.top=node.y+'px';renderStudioLinks();};element.onpointermove=move;element.onpointerup=()=>{element.onpointermove=null;studioSave();};};element.querySelector('.output').onpointerdown=event=>{event.stopPropagation();studioLinkSource=node.id;event.currentTarget.setPointerCapture(event.pointerId);};element.querySelector('.output').onpointerup=event=>{const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-studio-input]');if(target&&studioLinkSource&&target.dataset.studioInput!==studioLinkSource&&!studioLinks.some(link=>link.from===studioLinkSource&&link.to===target.dataset.studioInput)){studioLinks.push({id:'link-'+(++studioLinkSeq),from:studioLinkSource,to:target.dataset.studioInput,delay:0,direction:'none',moveTime:1});studioSelectedLink=studioLinks.at(-1).id;studioSave();}studioLinkSource=null;renderStudio();};canvas.append(element);});requestAnimationFrame(renderStudioLinks);renderStudioInspector();}
  function studioShow(open){studioView.hidden=!open;document.querySelector('.main').hidden=open;$('studio-nav').classList.toggle('active',open);$('library-nav').classList.toggle('active',!open);if(open)renderStudio();}
  async function teleop(direction){const speeds={forward:[.22,0,0],back:[-.18,0,0],left:[0,.16,0],right:[0,-.16,0]};if(direction==='stop'||!speeds[direction])return stopTeleop();if(!connected||!status.robot_connected)throw Error('Connect the robot before using teleop');const [vx,vy,omega]=speeds[direction];await request('/api/robot/teleop','POST',JSON.stringify({vx,vy,omega,duration:.35}),{'Content-Type':'application/json','X-G1-Safety-Confirmed':'YES'});$('teleop-state').textContent='Moving '+direction+'…';}
  async function stopTeleop(){if(teleopTimer){clearInterval(teleopTimer);teleopTimer=null;}teleopDirection=null;try{if(connected&&status.robot_connected&&!demo)await request('/api/robot/teleop/stop','POST','{}',{'Content-Type':'application/json'});}catch(error){errorToast(error.message);}if($('teleop-state'))$('teleop-state').textContent='Stopped';}
  function beginTeleop(direction){if(teleopDirection===direction)return;stopTeleop();teleopDirection=direction;teleop(direction).catch(error=>{errorToast(error.message);stopTeleop();});teleopTimer=setInterval(()=>teleop(direction).catch(error=>{errorToast(error.message);stopTeleop();}),220);}
  async function runStudio(){const incoming=new Set(studioLinks.map(link=>link.to));let node=studioNodes.find(value=>!incoming.has(value.id));if(!node){errorToast('Add a starting dance node before running the sequence.');return;}if(!connected||!status.robot_connected){errorToast('Connect the robot before running the sequence.');return;}const seen=new Set();try{$('studio-run').disabled=true;while(node&&!seen.has(node.id)){seen.add(node.id);if(node.kind!=='delay'){const item=studioNodeItem(node),path=item.kind==='unistore'?'/api/unistore/'+encodeURIComponent(item.id)+'/play':item.kind==='preset'?'/api/motions/'+encodeURIComponent(item.id)+'/play':'/api/routines/'+encodeURIComponent(item.id)+'/play';await request(path,'POST','{}',{'Content-Type':'application/json','X-G1-Safety-Confirmed':'YES'});await new Promise(resolve=>setTimeout(resolve,Math.max(1,node.duration||3)*1000));}const link=studioLinks.find(value=>value.from===node.id);if(!link)break;if(link.delay>0)await new Promise(resolve=>setTimeout(resolve,link.delay*1000));if(link.direction&&link.direction!=='none'){await teleop(link.direction);await new Promise(resolve=>setTimeout(resolve,link.moveTime*1000));await stopTeleop();}node=studioNodes.find(value=>value.id===link.to);}toast('Studio sequence completed.');}catch(error){errorToast(error.message);}finally{$('studio-run').disabled=false;stopTeleop();}}
  $('studio-nav').onclick=()=>studioShow(true);$('library-nav').onclick=()=>{studioShow(false);$('library').scrollIntoView({behavior:'smooth'});};$('studio-clear').onclick=()=>{studioNodes=[];studioLinks=[];studioSelectedLink=null;studioSave();renderStudio();};$('studio-add-delay').onclick=studioAddDelay;$('studio-run').onclick=runStudio;$('studio-canvas').ondragover=event=>event.preventDefault();$('studio-canvas').ondrop=event=>{event.preventDefault();try{const item=JSON.parse(event.dataTransfer.getData('application/g1-dance'));const rect=$('studio-canvas').getBoundingClientRect();studioAdd(item,event.clientX-rect.left,event.clientY-rect.top);}catch{}};$('studio-connection-form').onsubmit=event=>{event.preventDefault();const link=studioLinks.find(value=>value.id===studioSelectedLink);if(!link)return;link.delay=Math.max(0,Number($('studio-delay').value)||0);link.direction=$('studio-direction').value;link.moveTime=Math.max(.1,Number($('studio-move-time').value)||1);studioSave();renderStudio();};$('studio-delete-link').onclick=()=>{studioLinks=studioLinks.filter(value=>value.id!==studioSelectedLink);studioSelectedLink=null;studioSave();renderStudio();};document.querySelectorAll('[data-teleop]').forEach(button=>{const direction=button.dataset.teleop;button.onpointerdown=event=>{event.preventDefault();if(direction==='stop')stopTeleop();else beginTeleop(direction);};button.onpointerup=button.onpointerleave=button.onpointercancel=()=>{if(direction!=='stop')stopTeleop();};});document.addEventListener('keydown',event=>{if(studioView.hidden||event.target.matches('input,select,textarea')||event.repeat)return;const map={ArrowUp:'forward',ArrowDown:'back',ArrowLeft:'left',ArrowRight:'right'};if(map[event.key]){event.preventDefault();beginTeleop(map[event.key]);}});document.addEventListener('keyup',event=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key))stopTeleop();});window.addEventListener('blur',stopTeleop);studioLoad();
  // Native bundle defaults to the hotspot; browsers use their own server origin.
  if(!native)address=location.origin;
  refresh();refreshUniStore();setInterval(poll,2000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
